package main
import("bytes";"crypto/subtle";"encoding/base64";"encoding/json";"fmt";"io";"log";"net/http";"os";"strings";"sync";"time")
type Config struct{env,base,key,secret string;mock,consent bool;keys []string}
type Result struct{Found bool `json:"found"`;PIN *string `json:"pin"`;Name *string `json:"taxpayer_name"`;Environment string `json:"environment"`;Mock bool `json:"mock"`;Raw any `json:"raw"`}
type Token struct{value string;expires time.Time}
var cache=struct{sync.Mutex;m map[string]Token}{m:map[string]Token{}}
func get(k,d string)string{if v:=os.Getenv(k);v!=""{return v};return d}
func config()Config{e:=get("KRA_ENVIRONMENT","sandbox");b:="https://sbx.kra.go.ke";if e=="production"{b="https://api.kra.go.ke"};c:=Config{e,b,os.Getenv("KRA_PIN_CONSUMER_KEY"),os.Getenv("KRA_PIN_CONSUMER_SECRET"),get("KRA_MOCK","true")=="true",get("REQUIRE_CONSENT","true")!="false",strings.Split(os.Getenv("PROXY_API_KEYS"),",")};if c.mock&&e=="production"{log.Fatal("mock forbidden in production")};if !c.mock&&(c.key==""||c.secret==""){log.Fatal("KRA credentials required")};if len(c.keys)==1&&c.keys[0]==""{log.Fatal("PROXY_API_KEYS required")};return c}
func jsonCall(c *http.Client,method,url string,body any,headers map[string]string)(int,map[string]any,error){var rd io.Reader;if body!=nil{x,_:=json.Marshal(body);rd=bytes.NewReader(x)};r,_:=http.NewRequest(method,url,rd);if body!=nil{r.Header.Set("Content-Type","application/json")};for k,v:=range headers{r.Header.Set(k,v)};resp,e:=c.Do(r);if e!=nil{return 0,nil,e};defer resp.Body.Close();d:=map[string]any{};_ = json.NewDecoder(resp.Body).Decode(&d);return resp.StatusCode,d,nil}
func token(c Config,h *http.Client,key,secret string)(string,error){cache.Lock();defer cache.Unlock();if t,ok:=cache.m[key];ok&&t.expires.After(time.Now().Add(time.Minute)){return t.value,nil};auth:=base64.StdEncoding.EncodeToString([]byte(key+":"+secret));s,d,e:=jsonCall(h,"GET",c.base+"/v1/token/generate?grant_type=client_credentials",nil,map[string]string{"Authorization":"Basic "+auth});if e!=nil{return "",e};v,_:=d["access_token"].(string);if s>=400||v==""{return "",fmt.Errorf("KRA token request failed")};cache.m[key]=Token{v,time.Now().Add(time.Hour)};return v,nil}
func lookup(c Config,h *http.Client,byID bool,v,typ string)(Result,error){if c.mock{found:=(!byID&&v=="A000000000B")||(byID&&v=="00000000");if found{p,n:="A000000000B","DEMO T*****";return Result{true,&p,&n,c.env,true,nil},nil};return Result{false,nil,nil,c.env,true,nil},nil};key,secret,path:=c.key,c.secret,"/checker/v1/pinbypin";body:=map[string]string{"KRAPIN":v};if byID{key=get("KRA_PIN_BY_ID_CONSUMER_KEY",key);secret=get("KRA_PIN_BY_ID_CONSUMER_SECRET",secret);path="/checker/v1/pin";body=map[string]string{"TaxpayerType":typ,"TaxpayerID":v}};t,e:=token(c,h,key,secret);if e!=nil{return Result{},e};s,d,e:=jsonCall(h,"POST",c.base+path,body,map[string]string{"Authorization":"Bearer "+t});if e!=nil{return Result{},e};if s==404||fmt.Sprint(d["errorCode"])=="30002"{return Result{false,nil,nil,c.env,false,nil},nil};rec,_:=d["PINDATA"].(map[string]any);if rec==nil{rec=d};p,_:=rec["KRAPIN"].(string);n,_:=rec["Name"].(string);if s>=400||(p==""&&n==""){return Result{},fmt.Errorf("unexpected KRA response")};var pp,nn *string;if p!=""{pp=&p};if n!=""{nn=&n};return Result{true,pp,nn,c.env,false,nil},nil}
func write(w http.ResponseWriter,s int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(s);_=json.NewEncoder(w).Encode(v)}
func main(){c:=config();h:=&http.Client{Timeout:15*time.Second};var mu sync.Mutex;hits:=map[string][]time.Time{};mux:=http.NewServeMux();mux.HandleFunc("GET /health",func(w http.ResponseWriter,r *http.Request){write(w,200,map[string]any{"status":"ok","environment":c.env,"mock":c.mock})});mux.HandleFunc("POST /v1/pin/verify",func(w http.ResponseWriter,r *http.Request){serve(w,r,false,c,h,&mu,hits)});mux.HandleFunc("POST /v1/pin/verify-by-id",func(w http.ResponseWriter,r *http.Request){serve(w,r,true,c,h,&mu,hits)});log.Fatal(http.ListenAndServe(":"+get("PORT","8000"),mux))}
func serve(w http.ResponseWriter,r *http.Request,byID bool,c Config,h *http.Client,mu *sync.Mutex,hits map[string][]time.Time){k:=r.Header.Get("X-API-Key");valid:=false;for _,x:=range c.keys{x=strings.TrimSpace(x);if len(x)==len(k)&&subtle.ConstantTimeCompare([]byte(x),[]byte(k))==1{valid=true}};if !valid{write(w,401,map[string]string{"detail":"Invalid or missing X-API-Key"});return};mu.Lock();now:=time.Now();q:=[]time.Time{};for _,t:=range hits[k]{if now.Sub(t)<time.Minute{q=append(q,t)}};if len(q)>=30{mu.Unlock();write(w,429,map[string]string{"detail":"Rate limit exceeded"});return};hits[k]=append(q,now);mu.Unlock();var b struct{PIN string `json:"pin"`;ID string `json:"taxpayer_id"`;Type string `json:"taxpayer_type"`;Consent bool `json:"consent"`};if json.NewDecoder(http.MaxBytesReader(w,r.Body,65536)).Decode(&b)!=nil{write(w,422,map[string]string{"detail":"Invalid JSON"});return};if c.consent&&!b.Consent{write(w,400,map[string]string{"detail":"consent must be true"});return};v:=strings.TrimSpace(b.PIN);if byID{v=strings.TrimSpace(b.ID)}else{v=strings.ToUpper(v)};if len(v)<map[bool]int{true:5,false:9}[byID]||len(v)>20{write(w,422,map[string]string{"detail":"Invalid identifier format"});return};typ:=strings.ToUpper(b.Type);if typ==""{typ="KE"};out,e:=lookup(c,h,byID,v,typ);if e!=nil{write(w,502,map[string]any{"error":map[string]string{"code":"upstream_error","message":"KRA request failed"}});return};log.Printf("lookup by_id=%t found=%t",byID,out.Found);write(w,200,out)}
